#!/usr/bin/env python3
"""Write DarthNox's special moves and stats into his data files.

    python tools/darthnox_moves.py mods/darthnox/assets

Rewrites the generated part of darthnox.txt (everything after the
"# --- generated by tools/darthnox_moves.py ---" marker) and crescent.txt.
Edit the tables below and re-run; never hand-edit the generated part.

Frames written here carry a bdy:, so object_data.lua uses them whole instead of
Deep's. Frames with only hit_* fields keep Deep's mechanics and swap the inputs.
"""
import os, re, sys

CX, CY = 60, 85                   # sheet registration (autosprite_to_lf2.py output)
BODY = (CX - 17, CY - 72, 34, 72)  # standing hurtbox, relative to the cell
MARK = '# --- generated by tools/darthnox_moves.py ---'

# Inputs, put on standing (0-3), walking (5-8) and defend (110): D>A D^A DvA D>J DJA.
# D^J and DvJ are 0 so Deep's leftover moves can't be reached.
HITS = dict(Fa=235, Ua=270, Da=280, Fj=260, Uj=0, Dj=0, ja=240)

# Stats: a fast fencer. Speeds replace Deep's; defence lives in match.lua (armor 75).
MOVEMENT = {
    'walking_speed': 6.0, 'walking_speedz': 2.8,
    'running_speed': 10.5, 'running_speedz': 2.0,
    'jump_distance': 10.0, 'dash_distance': 19.0,
}

PARRY_FRAMES = (241, 243)         # combat.lua: a hit here starts the counter at 245
COUNTER_FRAME = 245


def itr(x, y, w, h, dvx=0, dvy=0, fall=0, vrest=0, arest=0, bdefend=0, injury=0, effect=1, kind=0):
    return (f'   itr:\n      kind: {kind}  x: {x}  y: {y}  w: {w}  h: {h}  dvx: {dvx}  dvy: {dvy}  fall: {fall}'
            f'  vrest: {vrest}  arest: {arest}  bdefend: {bdefend}  injury: {injury}  effect: {effect}\n   itr_end:\n')


def bdy(x, y, w, h):
    return f'   bdy:\n      kind: 0  x: {x}  y: {y}  w: {w}  h: {h}\n   bdy_end:\n'


def frame(n, name, pic, state, wait, nxt, dvx=0, dvy=0, mp=0, body=True, extra='', hits=None, cx=CX, cy=CY):
    head = f'   pic: {pic}  state: {state}  wait: {wait}  next: {nxt}  dvx: {dvx}  dvy: {dvy}  dvz: 0  centerx: {cx}  centery: {cy}'
    if mp:
        head += f'  mp: {mp}'
    if hits:
        head += '  ' + '  '.join(f'hit_{k}: {v}' for k, v in hits.items())
    return f'<frame> {n} {name}\n{head}\n{extra}{bdy(*BODY) if body else ""}<frame_end>\n'


# Sword hitbox in front of the chest; a lunge reaches further.
def blade(reach=48, **kw):
    return itr(CX + 4, CY - 58, reach, 28, **kw)


MOVES = [
    '# D>A  Crescent: a horizontal swing that launches a fast, light sword wave (crescent.txt)',
    frame(235, 'crescent', 32, 3, 2, 236, mp=60),
    frame(236, 'crescent', 33, 3, 1, 237),
    frame(237, 'crescent', 34, 3, 1, 238,
          extra=f'   opoint:\n      kind: 1  x: {CX + 30}  y: {CY - 42}  action: 0  dvx: 0  dvy: 0  oid: 62  facing: 0\n   opoint_end:\n'),
    frame(238, 'crescent', 34, 3, 5, 999),

    '# DJA  Parry: ~1 s guard (241-243). A hit landing in it is cancelled by combat.lua,\n'
    '# which jumps to 245: a huge unblockable stab that leaves the victim dizzy.',
    frame(240, 'parry', 36, 3, 1, 241, mp=200),
    frame(241, 'parry', 37, 3, 9, 242),
    frame(242, 'parry', 38, 3, 9, 243),
    frame(243, 'parry', 37, 3, 9, 244),
    frame(244, 'parry', 36, 3, 3, 999),
    frame(245, 'counter', 40, 3, 1, 246, body=False),
    frame(246, 'counter', 41, 3, 2, 247, dvx=14, body=False,
          extra=blade(62, dvx=4, fall=45, vrest=20, bdefend=100, injury=70)),
    frame(247, 'counter', 41, 3, 6, 248),
    frame(248, 'counter', 42, 3, 3, 999),

    '# D>J  Lunge: a fast forward stab that travels, with afterimages (sheet row 11)',
    frame(260, 'lunge', 44, 3, 1, 261, mp=75),
    frame(261, 'lunge', 45, 3, 2, 262, dvx=22, extra=blade(56, dvx=7, fall=40, vrest=15, bdefend=30, injury=40)),
    frame(262, 'lunge', 46, 3, 3, 263, extra=blade(56, dvx=7, fall=40, vrest=15, bdefend=30, injury=40)),
    frame(263, 'lunge', 42, 3, 4, 999),

    '# D^A  Rising slash: crouch, then an invincible upward sweep that launches, then fall',
    frame(270, 'rising', 48, 3, 1, 271, mp=100),
    frame(271, 'rising', 49, 3, 2, 272, dvx=3, dvy=-16, body=False,
          extra=itr(CX - 8, CY - 95, 58, 90, dvx=4, dvy=-14, fall=70, vrest=12, bdefend=60, injury=45)),
    frame(272, 'rising', 50, 3, 2, 273, extra=itr(CX - 4, CY - 92, 44, 60, dvx=3, dvy=-10, fall=70, vrest=12, bdefend=60, injury=20)),
    frame(273, 'rising', 50, 3, 6, 212),

    '# DvA  Flurry: rapid stabs with ghost blades; press A during it to keep stabbing',
    frame(280, 'flurry', 52, 3, 1, 281, mp=50),
    frame(281, 'flurry', 53, 3, 1, 282, extra=blade(50, dvx=1, fall=8, vrest=3, bdefend=8, injury=7)),
    frame(282, 'flurry', 54, 3, 1, 283, extra=blade(50, dvx=1, fall=8, vrest=3, bdefend=8, injury=7)),
    frame(283, 'flurry', 53, 3, 1, 284, extra=blade(50, dvx=1, fall=8, vrest=3, bdefend=8, injury=7)),
    frame(284, 'flurry', 54, 3, 1, 285, hits={'a': 281}, extra=blade(50, dvx=1, fall=8, vrest=3, bdefend=8, injury=7)),
    frame(285, 'flurry', 54, 3, 2, 286, extra=blade(54, dvx=6, fall=30, vrest=10, bdefend=16, injury=14)),
    frame(286, 'flurry', 52, 3, 3, 999),
]

BALL_CX, BALL_CY = 17, 32
BALL_BOX = (3, 4, 28, 56)


def ball():
    out = ['<bmp_begin>',
           'file(0-7): mods/darthnox/crescent.bmp  w: 34  h: 64  row: 4  col: 2',
           'weapon_hit_sound: data\\020.wav', 'weapon_drop_sound: data\\020.wav', 'weapon_broken_sound: data\\020.wav',
           '<bmp_end>', '',
           '# DarthNox\'s crescent wave: fast (dvx 22), light damage, knocks down (fall 70).',
           '# hit_a drains 20 of its hp per frame, so it flies ~25 frames (~550 px).', '']
    x, y, w, h = BALL_BOX
    for n in range(4):
        out.append(f'<frame> {n} flying\n   pic: {n}  state: 3000  wait: 1  next: {n + 1 if n < 3 else 999}  dvx: 22  dvy: 0'
                   f'  centerx: {BALL_CX}  centery: {BALL_CY}  hit_a: 20  hit_d: 40  hit_j: 0\n'
                   + itr(x, y, w, h, dvx=8, fall=70, vrest=10, bdefend=16, injury=16)
                   + bdy(x, y, w, h) + '<frame_end>\n')
    for base, name, st in ((10, 'hiting', 3001), (20, 'hit', 3002), (30, 'rebounding', 3003), (40, 'disappearing', 3004)):
        for i in range(4 if base < 40 else 3):
            pic = 4 + i if base < 40 else 5 + i
            last = (i == 3) if base < 40 else (i == 2)
            out.append(f'<frame> {base + i} {name}\n   pic: {pic}  state: {st}  wait: 1  next: {1000 if last else base + i + 1}'
                       f'  dvx: 0  dvy: 0  centerx: {BALL_CX}  centery: {BALL_CY}  hit_a: 0  hit_d: 0  hit_j: 0\n<frame_end>\n')
    return '\n'.join(out)


def main(assets):
    path = os.path.join(assets, 'darthnox.txt')
    text = open(path, encoding='utf-8').read().split(MARK)[0].rstrip() + '\n'
    # stats
    for key, value in MOVEMENT.items():
        text = re.sub(rf'^{key} [\d.-]+$', f'{key} {value:.6f}', text, flags=re.M)
    # every frame shares one registration
    text = re.sub(r'centerx: \d+  centery: \d+', f'centerx: {CX}  centery: {CY}', text)
    # inputs on standing/walking frames (drop any old hit_* first)
    def add_hits(m):
        n, body = int(m.group(1)), m.group(2)
        body = re.sub(r'  hit_\w+: -?\d+', '', body)
        if n in (0, 1, 2, 3, 5, 6, 7, 8):
            body = re.sub(r'(centery: \d+)', r'\1  ' + '  '.join(f'hit_{k}: {v}' for k, v in HITS.items()), body, count=1)
        return f'<frame> {n} {body}'
    text = re.sub(r'<frame> (\d+) (.*?<frame_end>)', add_hits, text, flags=re.S)
    gen = [MARK, '# Defend: the parry pose; specials start from here (hit_* as on standing)',
           frame(110, 'defend', 37, 7, 12, 999, body=False, hits=HITS),
           frame(111, 'defend', 37, 7, 0, 110, body=False)] + MOVES
    open(path, 'w', encoding='utf-8', newline='\n').write(text + '\n' + '\n'.join(gen))
    open(os.path.join(assets, 'crescent.txt'), 'w', encoding='utf-8', newline='\n').write(ball())
    print('wrote', path, 'and crescent.txt')


if __name__ == '__main__':
    if len(sys.argv) != 2:
        sys.exit(__doc__)
    main(sys.argv[1])
